From ee3be3c8eb97b6d56b8266cb02fc976e468641ea Mon Sep 17 00:00:00 2001
From: Tad Hunt <tad@exablox.com>
Date: Wed, 2 Sep 2015 14:23:17 -0700
Subject: [PATCH] fix Apple OSX build issue

Fix build issue introduced by commit 9b0b8c1cbd1d945fb096d6130f18c99ca901e567
"Local variable names shadowed global function names (e.g. read),
this would cause compile errors with gcc 4.4.7."

diff --git a/src/lib/kinetic_socket.c b/src/lib/kinetic_socket.c
index 96ff7d33..a229e7d6 100644
--- a/src/lib/kinetic_socket.c
+++ b/src/lib/kinetic_socket.c
@@ -165,7 +165,7 @@ void KineticSocket_BeginPacket(int fd)
     int on = 1;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &on, sizeof(on));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }

@@ -175,6 +175,6 @@ void KineticSocket_FinishPacket(int fd)
     int off = 0;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &off, sizeof(off));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by local variable names in the `kinetic_socket.c` file shadowing global function names, specifically the name `read`, which led to compile errors with GCC 4.4.7. This shadowing occurs when a local variable has the same name as a global function, causing ambiguity and confusion for the compiler.

        Commit message:
        fix Apple OSX build issue

Fix build issue introduced by commit 9b0b8c1cbd1d945fb096d6130f18c99ca901e567
"Local variable names shadowed global function names (e.g. read),
this would cause compile errors with gcc 4.4.7."  

        Patch:

 void KineticSocket_BeginPacket(int fd)
 {
 #if !defined(__APPLE__) /* TCP_CORK is NOT available on OSX */
     int on = 1;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &on, sizeof(on));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }

 void KineticSocket_FinishPacket(int fd)
 {
 #if !defined(__APPLE__) /* TCP_CORK is NOT available on OSX */
     int off = 0;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &off, sizeof(off));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }
-- 


        Provide a response strictly in the following format:
